import { NextResponse } from "next/server";
import { PDFDocument, degrees } from "pdf-lib";

export async function POST(req: Request) {
  const formData = await req.formData();
  const files = formData.getAll("files") as File[];
  const action = formData.get("action") as string;
  const rotationAngle = Number(
    formData.get("rotationAngle") || 90
  );

  if (!files || files.length === 0) {
    return NextResponse.json({ error: "No files" }, { status: 400 });
  }

  const pdfDocs = await Promise.all(
    files.map(async (file) => {
      const bytes = await file.arrayBuffer();
      return PDFDocument.load(bytes);
    })
  );

  let resultPdf = await PDFDocument.create();

  // ACCIONES


  if (action === "merge") {
    for (const doc of pdfDocs) {
      const pages = await resultPdf.copyPages(doc, doc.getPageIndices());
      pages.forEach((p) => resultPdf.addPage(p));
    }
  }

  if (action === "rotate") {
    const [doc] = pdfDocs;
    const pages = await resultPdf.copyPages(doc, doc.getPageIndices());
    pages.forEach((p) => {
      p.setRotation(degrees(rotationAngle));
      resultPdf.addPage(p);
    });
  }

  if (action === "compress") {
    const [doc] = pdfDocs;

    const pages = await resultPdf.copyPages(
      doc,
      doc.getPageIndices()
    );

    pages.forEach((p) => resultPdf.addPage(p));
  }

  if (action === "split") {
    return NextResponse.json(
      { error: "Split aún no implementado" },
      { status: 501 }
    );
  }

  const pdfBytes = await resultPdf.save();

  return new NextResponse(Buffer.from(pdfBytes), {
    headers: {
      "Content-Type": "application/pdf",
      "Content-Disposition": "attachment; filename=result.pdf",
    },
  });
}